/** Bundle exact SQL sources for serverless one-time bootstrap. No DB connection required. */
import { readFileSync, writeFileSync, mkdirSync } from 'node:fs';
import { resolve } from 'node:path';
const files=['01_schema.sql','02_logic.sql','03_seed.sql','05_upgrade_from_v2.sql'];
const data=files.map(filename=>({filename,sql:readFileSync(resolve('database',filename),'utf8')}));
mkdirSync(resolve('src/generated'),{recursive:true});
writeFileSync(resolve('src/generated/db-bundle.ts'),
`/* Generated by npm run db:bundle. Do not edit manually. */\nexport const sqlBundle: {filename:string;sql:string}[] = ${JSON.stringify(data,null,0)};\n`);
console.log('Bundled database SQL for Vercel runtime:',files.join(', '));
